CREATE TABLE IF NOT EXISTS admin_users (
  id INT AUTO_INCREMENT PRIMARY KEY,
  email VARCHAR(255) UNIQUE NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS site_content (
  id VARCHAR(50) PRIMARY KEY,
  data LONGTEXT NOT NULL,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS messages (
  id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  email VARCHAR(255) NOT NULL,
  message TEXT NOT NULL,
  is_read TINYINT(1) NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS visits (
  id INT AUTO_INCREMENT PRIMARY KEY,
  path VARCHAR(500) NOT NULL,
  referrer VARCHAR(500),
  user_agent VARCHAR(500),
  ip VARCHAR(64),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Seed with the content currently in src/data.js. Safe to run once — if you
-- run it again later it will OVERWRITE any edits made from /admin, so only
-- use this for first-time setup.
INSERT INTO site_content (id, data) VALUES ('main', '{"profile":{"name":"Iyeose Uhumuavbi","preferredName":"Simon","headline":"Data Scientist | Solving Complex Business Challenges with Predictive Analytics & Machine Learning","tagline":"Turning Data into Actionable Strategy","location":"Peterborough, England, United Kingdom","email":"hello@example.com","phone":"","availability":"Open to Data Science, Analytics Engineering & MLOps roles","github":"https://github.com/Iyeose","linkedin":"https://www.linkedin.com/in/iyeose-s-uhumuavbi","resumeUrl":"","photo":"/profile.jpg","about":"Results-oriented Data Scientist and creative problem solver with experience in large-scale data analysis, systems design, and operational optimization. Specialized in leveraging Microsoft Azure and Python to build automated pipelines and predictive models that solve critical business challenges in the Energy and Construction sectors.\n\nExtensive coding skills using Python (Pandas, Scikit-learn, NumPy) and SQL, with an advanced understanding of Azure Databricks, Azure Data Factory, Power BI, and Tableau. Skilled in the full software development lifecycle for data science, from hypothesis testing to model deployment and monitoring.\n\nStrategic thinker who combines rigorous statistical methods with a structured, detail-oriented approach derived from a background in Architecture. Excellent knowledge of Agile methodologies, with a proven track record of collaborating with cross-functional teams to deliver data-driven solutions that reduce costs and enhance operational efficiency.","pivotQuote":"I’ll always be an architect — but now I’m an architect with data.","topSkills":["Data Science","Data Analysis","Cloud Computing","Artificial Intelligence","Problem Solving"]},"siteConfig":{"logoImageDark":"/logo-night.png","logoImageLight":"/logo-day.png","logoInitials":"IU"},"stats":[{"value":"5+","label":"Years in Architecture"},{"value":"3.6M+","label":"Records Piped in Current Role"},{"value":"7","label":"End-to-End Data Projects"},{"value":"Distinction","label":"MSc Data Science, UEL"}],"experience":[{"role":"Data Analyst","org":"NIHR Cambridge Biomedical Research Centre","type":"Full-time · Hybrid","period":"Jun 2026 — Present","duration":"4 mos","location":"Cambridgeshire, England, United Kingdom","summary":"Driving a high-impact data science initiative at the NIHR BioResource, managing a longitudinal dataset of over 3.6 million participants — building Python pipelines and Power BI dashboards that translate recruitment and retention data into stakeholder insight, under strict data governance.","bullets":["Engineered a Python (Pandas/NumPy) pipeline to ingest and integrate disparate datasets, resolving data quality issues across 3.6M+ records.","Developed modular scripts for automated data hygiene and outlier detection, cutting manual processing time for complex variables.","Designed and deployed a multi-page Power BI dashboard suite with time-series recruitment trends and attrition heatmaps.","Used DAX to build socio-economic benchmarking metrics, surfacing representation gaps for stakeholders in real time.","Adhered to NIHR data governance and privacy-preserving analysis practices to protect participant anonymity.","Partnered with multidisciplinary teams to define KPIs and translate statistical output into strategic recommendations."],"tags":["Python","Power BI","DAX","Data Governance","Pandas"]},{"role":"Data Scientist Consultant","org":"AMDARI","type":"Contract · Remote","period":"Jan 2026 — Jul 2026","duration":"7 mos","location":"United Kingdom","summary":"Shipped four production ML systems spanning fraud detection, customer segmentation, multilingual NLP, and predictive maintenance — each taken from prototype to a monitored, deployed service.","bullets":["Built an end-to-end fraud detection system with XGBoost and LightGBM, lifting fraud recall by 15%; added SHAP for regulatory explainability and deployed via FastAPI + Docker with Evidently AI for drift monitoring.","Engineered a scalable RFM (Recency, Frequency, Monetary) segmentation framework using K-Means, with MLflow experiment tracking and GitHub Actions CI/CD, deploying dashboards on AWS EC2.","Architected a multilingual NLP pipeline using BERT Transformers to analyze 1M+ monthly reviews, automating preprocessing with spaCy/NLTK.","Built a time-series regression model to predict Remaining Useful Life (RUL) of hydraulic systems, deployed as a cloud-native AWS inference service that reduced unplanned industrial downtime."],"tags":["XGBoost","LightGBM","SHAP","FastAPI","Docker","MLflow","AWS","BERT","NLP"]},{"role":"Data Scientist","org":"LITEC GROUP","type":"Full-time · Hybrid","period":"Jul 2023 — Sep 2024","duration":"1 yr 3 mos","location":"Edo State, Nigeria","summary":"Bridged construction operations and data science — building extraction pipelines from BIM models and real-time BI dashboards that cut material costs and improved schedule visibility.","bullets":["Engineered a custom data extraction pipeline using the Revit API and Python to pull metadata from architectural models, automating Schedules of Quantities and reducing manual estimation errors.","Built Power BI dashboards integrated with Primavera P6 and Procore, giving stakeholders real-time visibility into Critical Path schedules, labor productivity and milestone variance.","Built automated cost-tracking models comparing historical procurement data with market fluctuations, helping negotiate a 10% reduction in material costs across three multi-story residential projects.","Used GIS and CAD data for site logistics analysis, optimizing placement of heavy machinery and material staging areas.","Translated architectural constraints and data insights into executive summaries for developers and investors."],"tags":["Revit API","Power BI","GIS","Python","Primavera P6"]},{"role":"Architect","org":"LITEC GROUP","type":"On-site","period":"Mar 2022 — Jun 2023","duration":"1 yr 4 mos","location":"Nigeria","summary":"Led defect surveys and as-built modeling, turning field observation into structured, analyzable data — the seed of the data-driven mindset that led to a career pivot.","bullets":["Led a team conducting conditional surveys of defective buildings, capturing precise on-site measurements and structural data.","Documented and categorized building defects in Excel-based analytical frameworks, linking physical symptoms to root causes.","Created high-fidelity as-built CAD/Revit models, mapping physical defects into digital twins for remediation planning.","Integrated occupant feedback data with physical survey results to sharpen root-cause defect analysis."],"tags":["Revit","CAD","Excel","Survey Analysis"]},{"role":"Data Coordinator","org":"ATO Architects Limited","type":"Contract","period":"Dec 2021 — Feb 2022","duration":"3 mos","location":"Federal Capital Territory, Nigeria","summary":"A short contract that opened the door — the first project where architecture and data science visibly overlapped.","bullets":["Conducted a building condition survey, collecting and analyzing measurement data in Excel to assess defects and maintenance needs.","Produced measured drawings and schedules in Revit & Excel, applying AI/computer vision on site photos to predict maintenance requirements.","Analyzed energy consumption patterns to support efficiency and sustainability improvements."],"tags":["Excel","Revit","Computer Vision"]}],"education":[{"school":"University of East London","credential":"MSc Data Science — Distinction","period":"Graduated 2026","detail":"Ranked 1st in the UK for Data Science & AI (NSS categories, 2025). Coursework spanned statistical inference, machine learning, big data technologies, and applied analytics — including a socio-economic determinants study on COVID-19 mortality (module DS7006)."}],"projects":[{"title":"ShopEase — Multilingual Sentiment Analysis & MLOps Pipeline","period":"Featured Project","image":"/projects/shopease.png","icon":"sentiment","description":"End-to-end NLP system for a European retailer receiving high volumes of multilingual customer feedback. Uncovered the \"Star Rating Fallacy\" — customers whose text sentiment directly contradicted their star rating — then built a production pipeline to extract the true voice of the customer.","highlights":["Cleaned 120K reviews down to ~3,300 high-quality, de-duplicated records after finding 116K+ synthetic duplicates causing data leakage risk.","Fine-tuned multilingual DistilBERT (55%+ non-English data across UK/FR/DE/ES) rather than translating, with confidence-based human-in-the-loop review for ambiguous cases.","Shipped as a dual-service architecture: FastAPI backend serving the model, Streamlit dashboard for business stakeholders, fully containerized with Docker."],"stack":["Python","PyTorch","Transformers (DistilBERT)","FastAPI","Streamlit","Docker"],"link":"https://github.com/Iyeose/Shop-Sentiment-Analysis"},{"title":"Optimizing Wastewater Energy Efficiency","period":"Unsupervised Learning + Power BI","image":"/projects/wastewater.jpg","icon":"wastewater","description":"6 years of operational data from a real-world wastewater plant. A supervised regression model failed to predict energy use, which led to a pivot: K-Means clustering revealed three distinct operating modes — including a \"Winter Slump\" where energy intensity nearly doubled due to thermal constraints, not pollution load.","highlights":["Identified Total Nitrogen — not hydraulic flow — as the #1 driver of energy consumption via feature importance analysis.","Segmented plant operation into 3 clusters (Sweet Spot, Summer/High Load, Winter Slump) using K-Means.","Built an interactive Power BI dashboard translating the clustering results into operational recommendations for plant engineers."],"stack":["Python","Scikit-learn","K-Means","Random Forest","Power BI","DAX"],"link":"https://github.com/Iyeose/Optimizing-Wastewater-Energy-Efficiency-using-Unsupervised-Learning"},{"title":"Telco Customer Churn — Segmented ML Analysis","period":"Predictive Analytics","image":"/projects/telco-churn.png","icon":"churn","description":"Went beyond a single global churn model by segmenting customers by contract type (Month-to-Month, One-Year, Two-Year) and training specialized models per segment — surfacing distinct churn drivers a \"one-size-fits-all\" model would have hidden.","highlights":["Tuned XGBoost achieved 0.816 recall and 0.846 ROC-AUC on the global model; segmented Random Forest hit 0.710 recall for Month-to-Month churners.","Found Fiber Optic service and low tenure as the dominant churn signal for Month-to-Month customers, while streaming add-ons drove churn for One-Year customers.","Delivered actionable, segment-specific retention recommendations from feature importance analysis."],"stack":["Python","Scikit-learn","XGBoost","Random Forest","Pandas"],"link":"https://github.com/Iyeose/Telco-Customer-Churn-Analysis-Prediction"},{"title":"Data-Driven Prediction of Human Thermal Comfort","period":"Applied Machine Learning","image":"/projects/thermal-comfort.jpg","icon":"thermal","description":"Benchmarked ML models against traditional comfort models (PMV, Adaptive Comfort) using the 100K+ entry ASHRAE Global Thermal Comfort Database II, to find what actually drives human comfort in buildings.","highlights":["Tuned XGBoost reached 53.1% accuracy — a 130% improvement over the 23% baseline Logistic Regression.","Handled severe class imbalance with SMOTE and engineered environmental, personal and contextual features.","Random Forest emphasized physical/personal drivers (temperature, age, clothing); XGBoost emphasized climate context — together showing comfort depends on both."],"stack":["Python","XGBoost","Random Forest","SVM","Keras/TensorFlow","SMOTE"],"link":"https://github.com/Iyeose/Data-Driven-Prediction-of-Human-Thermal-Comfort"},{"title":"Predicting Building Energy Consumption","period":"Sustainable Architecture × ML","image":"","icon":"building","description":"Applied to the intersection of his two careers: predicting a residential building''s Heating and Cooling Load directly from design parameters, before a single brick is laid — so architects can choose materials that cut energy demand at the design stage.","highlights":["ANN and Random Forest reached R² of 0.997 for Heating Load prediction, far outperforming a Decision Tree baseline.","Identified Glazing Area as the most influential design feature, ahead of surface area and wall area.","Used Spearman and partial correlation analysis for careful feature selection, avoiding data leakage during standardization."],"stack":["R","Random Forest","SVM","Artificial Neural Network"],"link":"https://github.com/Iyeose/Predicting-Building-Energy-Consumption"},{"title":"Socioeconomic Factors in COVID-19 Mortality (England)","period":"MSc Coursework — Statistical Modeling","image":"","icon":"health","description":"Academic research (Module DS7006, University of East London) investigating which socioeconomic and demographic variables most influenced COVID-19 mortality across English local authorities during 2020.","highlights":["Applied PCA, Spearman correlation, and multiple linear regression, with VIF checks for multicollinearity.","Found deprivation level and housing conditions were strongly associated with higher mortality, more so than some demographic factors.","Merged multi-source data (census, mortality, boundary changes) via a custom SQLite pipeline."],"stack":["R","SQLite","ggplot2","PCA","Regression"],"link":"https://github.com/Iyeose/THE-SOCIOECONOMIC-FACTOR-THAT-AFFECTS-COVID-19-DEATHS-IN-ENGLAND-"},{"title":"Superstore Sales Analysis","period":"Business Intelligence","image":"/projects/superstore.jpg","icon":"retail","description":"End-to-end retail analysis of a superstore''s sales, profit, customer segments and shipping performance, delivered as a stakeholder-ready dashboard.","highlights":["Surfaced $2.3M in total sales and $286K in profit, with California as the top-performing state ($457K).","Found Technology led on margin while Furniture underperformed — informing category-level recommendations.","Flagged that Standard shipping (~60% of orders) had longer durations that hurt customer experience."],"stack":["Excel","Pivot Tables","Dashboarding"],"link":"https://github.com/Iyeose/Superstore-Sales-Analysis"}],"skillGroups":[{"label":"Languages & Core","items":[{"name":"Python","level":95},{"name":"SQL","level":85},{"name":"R","level":75},{"name":"DAX","level":70}]},{"label":"ML / AI","items":[{"name":"Scikit-learn","level":90},{"name":"XGBoost","level":90},{"name":"K-Means","level":85},{"name":"LightGBM","level":80},{"name":"Transformers (BERT/DistilBERT)","level":80},{"name":"SHAP","level":75},{"name":"PyTorch","level":75},{"name":"spaCy / NLTK","level":70}]},{"label":"MLOps & Cloud","items":[{"name":"Microsoft Azure","level":85},{"name":"Azure Databricks","level":80},{"name":"Azure Data Factory","level":80},{"name":"Docker","level":80},{"name":"FastAPI","level":80},{"name":"MLflow","level":75},{"name":"AWS EC2","level":70},{"name":"GitHub Actions","level":70},{"name":"Evidently AI","level":65}]},{"label":"BI & Visualization","items":[{"name":"Power BI","level":90},{"name":"Excel","level":90},{"name":"Streamlit","level":80},{"name":"Tableau","level":75}]},{"label":"From Architecture","items":[{"name":"Revit API","level":85},{"name":"CAD","level":85},{"name":"GIS","level":70},{"name":"Primavera P6","level":70},{"name":"Procore","level":65}]}]}')
